args.command:
node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { permit } from './limit.mjs';
const cases = [
  [-1, false],
  [0, true],
  [3, true],
  [4, false],
  ['3', false],
  [null, false],
  [NaN, false],
  [1.5, false],
  [undefined, false],
  [Infinity, false],
  [-Infinity, false],
];
for (const [input, expected] of cases) {
  assert.equal(permit(input), expected, `permit(${String(input)})`);
}
console.log('targeted QUAL-1 probe passed', cases.length, 'cases');
EOF
